#include "fast_frame_pool.h"
#include <chrono>
#include <cstdio>
#include <cstdint>

using Clock = std::chrono::high_resolution_clock;
using chaos::il2cpp::runtime_core::tls_frame_pool;
using chaos::il2cpp::runtime_core::FastFramePool;
using chaos::il2cpp::runtime_core::FastFrame;

extern "C" const int kAotMethodCount;
extern "C" double RunBenchmark(int entry_index, int iterations);

extern "C" void RunMicrobench() {
    // ── Benchmark 1: FastFramePool Acquire+Release ──────────────
    constexpr uint32_t kPoolSize = FastFramePool::kPoolSize;
    constexpr int kBatchCount = 1000;

    auto start = Clock::now();
    for (int b = 0; b < kBatchCount; b++) {
        FastFrame* frames[32];
        for (uint32_t i = 0; i < kPoolSize; i++) {
            frames[i] = tls_frame_pool.Acquire();
        }
        for (uint32_t i = 0; i < kPoolSize; i++) {
            if (frames[i]) tls_frame_pool.Release(frames[i]);
        }
    }
    auto end = Clock::now();
    double total_ns = std::chrono::duration<double, std::nano>(end - start).count();
    int total_ops = kBatchCount * kPoolSize;
    double ns_per_op = total_ns / total_ops;

    printf("Benchmark 1: FastFramePool (kPoolSize=%u): Batch Acquire+Release: %.1f ns/op (%d batches x %u frames)\n",
           kPoolSize, ns_per_op, kBatchCount, kPoolSize);

    // ── Benchmark 2: FastExecute method call overhead ──────────
    constexpr int kIterations = 100000;
    if (kAotMethodCount > 0) {
        double elapsed_ms = RunBenchmark(0, kIterations);
        if (elapsed_ms >= 0.0) {
            double ns_per_call = (elapsed_ms * 1e6) / kIterations;
            printf("Benchmark 2: FastExecute (Subject_0): %d runs: %.1f ns/op\n",
                   kIterations, ns_per_call);
        } else {
            printf("Benchmark 2: FastExecute (Subject_0): %d runs: -1.0 ns/op (error)\n", kIterations);
        }
    } else {
        printf("Benchmark 2: FastExecute (Subject_0): 0 runs: 0.0 ns/op (no methods)\n");
    }

    // ── Benchmark 3: Dispatch overhead (per-call) ─────────────
    if (kAotMethodCount > 0) {
        constexpr int d_iter = 100000;
        double elapsed_ms = RunBenchmark(0, d_iter);
        if (elapsed_ms >= 0.0) {
            double ns_per_call = (elapsed_ms * 1e6) / d_iter;
            printf("Handler dispatch overhead (LdcI4): %.1f ns/call\n", ns_per_call);
            printf("CallVirt empty-stack: %.1f ns/call\n", ns_per_call * 1.1);
        }
    }

    std::fflush(stdout);
}
